<?php
require_once __DIR__.'/includes/bootstrap.php'; require_login();
$u=current_user();$id=(int)($_GET['id']??$_POST['ticket_id']??0);$error='';$notice='';
$st=$db->prepare('SELECT t.*,s.service_name,s.domain_name FROM support_tickets t LEFT JOIN customer_services s ON s.id=t.service_id WHERE t.id=? AND t.user_id=? LIMIT 1');$st->execute([$id,$u['id']]);$ticket=$st->fetch();if(!$ticket){http_response_code(404);exit('Ticket not found.');}
if(is_post()){verify_csrf();public_form_guard($db, 'ticket_reply', $_POST['recaptcha_token'] ?? '');$action=$_POST['action']??'reply';try{$db->beginTransaction();if($action==='reply'){$message=trim($_POST['message']??'');if($message==='')throw new RuntimeException('Reply cannot be empty.');if($ticket['status']==='closed')throw new RuntimeException('This ticket is closed. Open a new ticket for a new issue.');$db->prepare('INSERT INTO support_ticket_messages(ticket_id,sender_user_id,sender_role,message) VALUES(?,?,?,?)')->execute([$id,$u['id'],'client',$message]);$msgId=(int)$db->lastInsertId();$db->prepare("UPDATE support_tickets SET status='open' WHERE id=?")->execute([$id]);$db->prepare('INSERT INTO support_ticket_events(ticket_id,actor_user_id,event_type,details) VALUES(?,?,?,?)')->execute([$id,$u['id'],'customer_reply','Customer replied to ticket']);if(isset($_FILES['attachment'])&&$_FILES['attachment']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['attachment'];if($f['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Attachment upload failed.');if((int)$f['size']>5*1024*1024)throw new RuntimeException('Attachment must be 5 MB or smaller.');$allowed=['pdf'=>'application/pdf','png'=>'image/png','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','webp'=>'image/webp','txt'=>'text/plain','zip'=>'application/zip'];$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!isset($allowed[$ext])||($mime!==$allowed[$ext]&&!(in_array($ext,['jpg','jpeg'],true)&&$mime==='image/jpeg')))throw new RuntimeException('Unsupported attachment type.');$stored=bin2hex(random_bytes(16)).'.'.$ext;$dest=__DIR__.'/uploads/tickets/'.$stored;if(!is_dir(dirname($dest))||!is_writable(dirname($dest)))throw new RuntimeException('Private attachment storage is not writable.');if(!move_uploaded_file($f['tmp_name'],$dest))throw new RuntimeException('Could not store attachment.');$db->prepare('INSERT INTO support_ticket_attachments(ticket_id,message_id,user_id,original_name,stored_name,mime_type,file_size,sha256) VALUES(?,?,?,?,?,?,?,?)')->execute([$id,$msgId,$u['id'],substr($f['name'],0,255),$stored,$mime,(int)$f['size'],hash_file('sha256',$dest)]);}}elseif($action==='close'){$db->prepare("UPDATE support_tickets SET status='closed',closed_at=NOW() WHERE id=? AND status<>'closed'")->execute([$id]);$db->prepare('INSERT INTO support_ticket_events(ticket_id,actor_user_id,event_type,details) VALUES(?,?,?,?)')->execute([$id,$u['id'],'ticket_closed','Customer closed ticket']);}$db->commit();if($action==='reply'){wdh_queue_email($db,support_admin_email($db),'Customer replied — '.$ticket['ticket_number'],'Customer '.$u['full_name'].' ('.$u['email'].') replied to support ticket '.$ticket['ticket_number'].'.\n\n'.$message,'support_reply',null,$ticket['order_id']?:null,$ticket['service_id']?:null);wdh_log_communication($db,$message,$ticket['subject'],$u['id'],null,$ticket['order_id']?:null,$ticket['service_id']?:null,'support','client');}$notice=$action==='close'?'Ticket closed.':'Reply sent.';}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}
