?><!doctype html><html lang="<?=e($LANG)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($ticket['ticket_number'])?> — WDH Support</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="portal-page"><div class="breadcrumbs">Home › Client Portal › Support › <?=e($ticket['ticket_number'])?></div><div class="portal-welcome"><div><span class="eyebrow mint"><?=e(strtoupper($ticket['category']))?></span><h1><?=e($ticket['subject'])?></h1><p><?=e($ticket['ticket_number'])?> · <?=e(ucfirst($ticket['status']))?> · Priority <?=e(ucfirst($ticket['priority']))?></p></div><a class="btn secondary" href="support.php">All Tickets</a></div><?php if($notice):?><div class="alert success-alert"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><section class="cart-card"><div class="ticket-thread"><?php foreach($messages as $m):?><article class="ticket-message"><div class="ticket-message-head"><strong><?=e($m['sender_role']==='admin'?'WDH Support':($m['full_name']?:'You'))?></strong><span><?=e($m['created_at'])?></span></div><div><?=nl2br(e($m['message']))?></div><?php $as=$db->prepare('SELECT id,original_name FROM support_ticket_attachments WHERE message_id=?');$as->execute([$m['id']]);$atts=$as->fetchAll();foreach($atts as $a):?><a class="small" href="ticket-attachment.php?id=<?=$a['id']?>">📎 <?=e($a['original_name'])?></a><?php endforeach;?></article><?php endforeach;?></div></section><?php if($ticket['status']!=='closed'):?><section class="cart-card"><h2>Reply</h2><form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="text" name="website" value="" class="hp-field" tabindex="-1" autocomplete="off" aria-hidden="true"><?=recaptcha_field('ticket_reply')?><input type="hidden" name="ticket_id" value="<?=$id?>"><textarea name="message" rows="7" required placeholder="Write your reply..."></textarea><label>Attachment (optional, max 5 MB)<input type="file" name="attachment" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.zip"></label><button class="btn primary" name="action" value="reply">Send Reply →</button></form><form method="post" style="margin-top:10px"><?=csrf_field()?><input type="hidden" name="ticket_id" value="<?=$id?>"><button class="btn secondary" name="action" value="close">Close Ticket</button></form></section><?php else:?><div class="alert">This ticket is closed.</div><?php endif;?></main><?php require __DIR__.'/includes/footer.php';?></body></html>
